  it("rejects branching amendment chains", () => invalid(p => { (p.filingLedgerEntries as FecV2GraphRow[]).push(row({ ledger_sha256: hash(5000), file_number: "two" }), row({ ledger_sha256: hash(5000), file_number: "three" })); (p.amendmentLinks as FecV2GraphRow[]).push(row({ ledger_sha256: hash(5000), file_number: "two", predecessor_file_number: "file" }), row({ ledger_sha256: hash(5000), file_number: "three", predecessor_file_number: "file" })); }));
  it("rejects a sanitized filing with a wrong file", () => invalid(p => (p.sanitizedFilings[0] as Record<string, unknown>).file_number = "wrong"));
  it("rejects bad alternate scoping", () => invalid(p => (p.alternateScoping as FecV2GraphRow[]).push(row({ ledger_sha256: hash(5000), file_number: "file", sanitized_artifact_sha256: hash(5001), conclusion: "inside" }))));
  it("handles bigint maxima without numeric overflow", () => { const p = fixture(); const max = BigInt("999999999999999999999999999999999999999999999999999999"); for (const collection of [p.coverage, p.aggregates]) { (collection[0] as Record<string, unknown>).support_cents = max; (collection[0] as Record<string, unknown>).oppose_cents = max; } (p.coverage[0] as Record<string, unknown>).outcome = "complete_nonzero"; expect(() => validateFecV2PublicationGraph(p)).not.toThrow(); });
