    (p as unknown as { artifacts: FecV2GraphRow[] }).artifacts = receipts.map(item => row({ plan_sha256: plan, artifact_sha256: item.artifactSha256, artifact_kind: item.artifactKind, canonical_byte_size: BigInt(item.byteSize) }));
    (p as unknown as { enumerationPages: FecV2GraphRow[] }).enumerationPages = pageDescriptors.map((item, i) => row({ plan_sha256: plan, artifact_sha256: item.artifactSha256, artifact_kind: "enumeration_page", pass: i < 2 ? 1 : 2, form_type: "F24", receipt_date: "2026-01-02", requested_file_number: null, page_number: i % 2 + 1, terminal: i % 2 }));
    (p as unknown as { filingLedgers: FecV2GraphRow[] }).filingLedgers = [row({ plan_sha256: plan, artifact_sha256: ledgerDescriptor.artifactSha256, artifact_kind: "filing_ledger", stable: 1, finalized_at: cutoff })];
    (p as unknown as { filingLedgerEntries: FecV2GraphRow[] }).filingLedgerEntries = [row({ plan_sha256: plan, ledger_sha256: ledgerDescriptor.artifactSha256, file_number: "12", entry_identity_sha256: entryIdentitySha256, canonical_form_type: "F24", base_form_type: "F24", report_type: "M12", report_date: null, receipt_date: "2026-01-02", coverage_start: null, coverage_end: null, amendment_indicator: "N", filer_id: "H00000001", committee_id: "C00000001", electronic_status: "electronic", raw_source_availability: "available" })];
